import { expect, expectStatus, test } from "../../fixtures";

// Declared with test.skip(): the OpenAPI spec marks POST /api/auth/logout as deprecated
// until the cookie rewrite ships, and a running test fails the release.
test.describe("sign out", () => {
  test.skip("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");

    // Act
    const response = await member.post("/api/auth/logout");

    // Assert
    expect(response.status()).toBe(204);
    const cookie = response
      .headersArray()
      .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
    expect(cookie, "session cookie should be present in Set-Cookie").toBeDefined();
    expect(cookie?.value.split(";")[0]).toBe("session=");
    expect(cookie?.value.toLowerCase()).toMatch(/max-age=0|expires=thu, 01 jan 1970/);
  });
});
